import Link from "next/link";
import { getFrameworksSlugs, getFrameworksMeta } from "@/lib/frameworks";

/** frameworks index — lists every MDX item. Generated by the Webflow Cloner agent. */
export default function FrameworksIndex() {
  const items = getFrameworksSlugs().map(getFrameworksMeta)
    .sort((a, b) => (b.date ?? "").localeCompare(a.date ?? ""));
  return (
    <main style={{ maxWidth: 880, margin: "0 auto", padding: "4rem 1.25rem" }}>
      <h1>frameworks</h1>
      <ul style={{ listStyle: "none", padding: 0, display: "grid", gap: 24 }}>
        {items.map((it) => (
          <li key={it.slug}>
            <Link href={`/frameworks/${it.slug}`}>
              <h2>{it.title}</h2>
              {it.excerpt ? <p>{it.excerpt}</p> : null}
            </Link>
          </li>
        ))}
      </ul>
    </main>
  );
}
